create extension if not exists pgcrypto;
alter table public.profiles add column if not exists first_name text check(char_length(first_name)<=80),add column if not exists last_name text check(char_length(last_name)<=80),add column if not exists preferred_language text default 'en' check(preferred_language in('en','ar')),add column if not exists preferred_size text,add column if not exists preferred_colors text[] default '{}',add column if not exists preferred_categories text[] default '{}',add column if not exists marketing_consent boolean default false,add column if not exists created_at timestamptz default now();
alter table public.user_state add column if not exists preferences jsonb not null default '{}',add column if not exists version bigint not null default 1;
create index if not exists user_state_updated_idx on public.user_state(updated_at desc);create index if not exists profiles_updated_idx on public.profiles(updated_at desc);
create table if not exists public.addresses(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,label text check(char_length(label)<=40),first_name text not null,last_name text not null,line1 text not null,line2 text,city text not null,region text,postal_code text,country text not null,phone text,is_default boolean default false,created_at timestamptz default now(),updated_at timestamptz default now());
create index if not exists addresses_user_idx on public.addresses(user_id);create unique index if not exists one_default_address_per_user on public.addresses(user_id) where is_default;
alter table public.addresses enable row level security;drop policy if exists "addresses owner" on public.addresses;create policy "addresses owner" on public.addresses for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create or replace function public.delete_own_account() returns void language plpgsql security definer set search_path=public as $$begin delete from auth.users where id=auth.uid();end;$$;revoke all on function public.delete_own_account() from public;grant execute on function public.delete_own_account() to authenticated;
